import fs from "node:fs";
const root = process.argv[2];
const prefix = process.argv[3] ?? "paired";
const rounds = Number(process.argv[4] ?? "3");
const pattern = new RegExp("^" + prefix + "-(.+)-(\\d+)-(baseline|candidate)\\.log$");
const files = fs.readdirSync(root);
const whole = [], lanes = [];
for (const name of files) {
  const m = name.match(pattern);
  if (!m) continue;
  const fixture = m[1], round = Number(m[2]), variant = m[3];
  const contents = fs.readFileSync(root + "/" + name, "utf8");
  if (["selected", "chord", "radial", "contacts", "overlaps"].includes(fixture) &&
      !contents.includes("test result: ok. 1 passed; 0 failed; 0 ignored;"))
    throw new Error("Incomplete test: " + name);
  const time = root + "/" + name.replace(/\.log$/, ".time");
  if (fs.existsSync(time)) {
    const values = Object.fromEntries([...fs.readFileSync(time, "utf8").matchAll(/(\w+)=([0-9.]+)/g)].map(m => [m[1], Number(m[2])]));
    if (values.exit !== 0) throw new Error("Unsuccessful process: " + name);
    whole.push({fixture, round, variant, ...values});
  }
  for (const line of contents.split("\n")) {
    let m = line.match(/^([^:]+): (\d+) (?:iterations|curves) in ([0-9.]+)(ns|µs|ms|s) /);
    if (m) {
      const iterations = Number(m[2]), total_ns = Number(m[3]) * ({ns:1,"µs":1000,ms:1000000,s:1000000000})[m[4]];
      lanes.push({fixture, round, variant, name:m[1], iterations, total_ns, ns_per_iter:total_ns/iterations, output:line});
      continue;
    }
    m = line.match(/^([^:]+): (\d+) iterations, total_ns=(\d+), ns_per_iter=(\d+),/);
    if (m) {
      const iterations = Number(m[2]), total_ns = Number(m[3]);
      lanes.push({fixture, round, variant, name:m[1], iterations, total_ns, ns_per_iter:total_ns/iterations, output:line});
    }
  }
}
const median = xs => { const sorted = xs.toSorted((a,b)=>a-b); return sorted[(sorted.length-1)/2]; };
const compare = (rows, key, value) => [...new Set(rows.map(key))].map(name => {
  const baseline = rows.filter(r => key(r) === name && r.variant === "baseline").map(r=>r[value]);
  const candidate = rows.filter(r => key(r) === name && r.variant === "candidate").map(r=>r[value]);
  if (baseline.length !== rounds || candidate.length !== rounds) throw new Error("Unpaired " + name);
  const before = median(baseline), after = median(candidate);
  return {name, baseline, candidate, baseline_median:before, candidate_median:after, change_percent:100*(after/before-1)};
});
const instructions = ["rectangles","circles","capsules","overlaps"].map(fixture => {
  const values = ["baseline","candidate"].map(variant => {
    const contents = fs.readFileSync(root+"/instructions-"+fixture+"-"+variant+".callgrind","utf8");
    const summary = Number(contents.match(/^summary: (\d+)$/m)?.[1]);
    const total = Number(contents.match(/^totals: (\d+)$/m)?.[1]);
    if (!summary || summary !== total) throw new Error("Incomplete Callgrind result");
    return summary;
  });
  return {fixture, baseline:values[0], candidate:values[1], change_percent:100*(values[1]/values[0]-1)};
});
console.log(JSON.stringify({
  cpu:7, alternating_order:Array.from({length:rounds}, (_, index) => index % 2 ? "candidate,baseline" : "baseline,candidate"),
  invocations:files.filter(f=>pattern.test(f)).length,
  whole_process_measurements:whole,
  whole_process_summary:compare(whole,r=>r.fixture,"elapsed_s"),
  lane_measurements:lanes,
  lane_summary:compare(lanes,r=>r.fixture+"/"+r.name,"ns_per_iter").sort((a,b)=>b.change_percent-a.change_percent),
  instructions
}, null, 2));

