#!/usr/bin/env bash
set -euo pipefail
verification_root="$1"
node --input-type=module -e '
import fs from "node:fs";
const root=process.argv[1];
const report=JSON.parse(fs.readFileSync(root+"/checkpoint.json", "utf8"));
const seen=new Set();
for (const item of report.artifacts) {
    if (!item.path.startsWith(root+"/") || /[\r\n\\]/.test(item.path) ||
        !/^[0-9a-f]{64}$/.test(item.sha256) || seen.has(item.path) ||
        fs.statSync(item.path).size !== item.bytes) throw Error("Invalid artifact: "+item.path);
    seen.add(item.path);
    console.log(item.sha256+"  "+item.path);
}
if (!seen.size) throw Error("Empty artifact set");
' "$verification_root" > "$verification_root/artifact-sha256.manifest"
sha256sum --check "$verification_root/artifact-sha256.manifest" > "$verification_root/artifact-sha256-audit.log"
